    f={'id':lambda m:m,'r90':lambda m:np.rot90(m,-1),'r180':lambda m:np.rot90(m,2),'r270':lambda m:np.rot90(m,1),
       'lr':np.fliplr,'ud':np.flipud,'T':lambda m:m.T,'aT':lambda m:np.rot90(m.T,2)}[nm]
    return np.asarray(f(rect))
